INSERT INTO tenants (slug, name, status, config, rate_per_min, rate_per_day, note)
VALUES ('chainonjoli', 'chainonjoli（シェノンジョリ）', 'active', '{"brand":{"name":"chainonjoli","reading":"シェノンジョリ","mark":"Cj","eyebrow":"FACIAL ESTHETIC SALON — ISE","tagline":"肌を整え、心を癒す。伊勢市の隠れ家プライベートエステ","heroLine":"— たった90分で、心がふっと軽くなる場所。","demoIntro":"伊勢市の隠れ家エステサロン「chainonjoli（シェノンジョリ）」を題材に、実際に操作できます。"},"theme":{"accent":"#A18072","accentDeep":"#82655A","accentSoft":"#F0E7E1"},"contact":{"lineUrl":"https://lin.ee/O1jhrwd","tel":"08042231203","telDisplay":"080-4223-1203","telNote":"営業時間 9:00–20:00（施術中は折り返し）"},"home":{"cards":[{"pill":"MEMBER","tone":"gold","title":"会員価格のご案内　フェイシャルエステ ¥3,300","body":"ビジター ¥8,800。会員制度の詳細は公式LINEでお気軽にお尋ねください。"},{"pill":"公式LINE","tone":"sage","title":"予約・変更・商品注文まで、LINEで完結","body":"肌のご相談も匿名でどうぞ。小さな疑問も気軽に送ってください。","cta":"LINEで友だち追加","action":"line"}]},"menu":{"sections":[{"title":"Facial Esthetic","items":[{"name":"フェイシャルエステ（ビジター）","desc":"カウンセリング＋フェイシャル・リンパケア 約90分","price":"¥8,800"},{"name":"美白コース／保湿コース","desc":"選べる集中ケア　90分＋パック付き","price":"¥11,000"},{"name":"フェイシャルエステ（会員）","desc":"会員登録をされている方の特別価格","price":"¥3,300"}]}],"highlight":{"title":"施術はお悩みに合わせてカスタマイズ","body":"くすみ・たるみ・ニキビ・乾燥・敏感肌など、その日のお肌に合わせて内容と力加減を調整します。施術後はドレッサーでメイク直しができ、ご希望の方にはメイクアップサービスもございます。"},"note":"表示は税込価格です。どんなケアが合うか迷ったら、AIカウンセラーにご相談ください。"},"access":{"mapLabel":"MAP（Googleマップ連携予定）","rows":[["所在地","三重県伊勢市宇治浦田二丁目<br>469-48（進修小学校前）"],["お電話","<a href=\"tel:08042231203\" style=\"color:var(--accent-deep);font-weight:600;text-decoration:none\">080-4223-1203</a>"],["営業時間","9:00–20:00"],["定休日","不定休（完全予約制）"],["お車の方","駐車についてはご予約時に<br>LINEでお気軽にお尋ねください"]],"cancel":{"title":"ご予約の変更・キャンセル","body":"公式LINE、またはお電話（080-4223-1203）で承ります。当サロンは完全予約制のプライベート空間です。体調不良の際は遠慮なくご相談ください。"}},"reserve":{"intro":"ご都合の良い方法をお選びください。いずれも1分ほどで完了します。","lineNote":"空き枠の確認・変更もトークで完結","webNote":"希望日時を送信 → サロンから確定連絡","disclaimer":"完全予約制です。ご予約の変更・キャンセルは公式LINEまたはお電話で承ります。"},"reception":{"greeting":"こんにちは、chainonjoli（シェノンジョリ）のAI受付です🛎\n営業時間・料金・駐車場など、なんでもお尋ねください。深夜でもすぐお答えします。","faq":{"営業時間":"営業時間は 9:00〜20:00、不定休の完全予約制です。\nご予約・お問い合わせは24時間、公式LINEで受け付けています。","メニューと料金":"メニューはフェイシャルエステ（フェイシャル・リンパケア／約90分）です。\n\n・ビジター価格 ¥8,800\n・美白コース／保湿コース（90分＋パック付き）¥11,000\n・会員価格 ¥3,300\n\n施術内容はお悩みに合わせてカスタマイズします。どんなケアが合うか迷ったら、AIカウンセラーが3つの質問でご提案します。","アクセス・駐車場":"三重県伊勢市宇治浦田二丁目469-48（進修小学校前）です。\nお車でお越しの際の駐車については、ご予約時にLINEでお気軽にお尋ねください。","キャンセルについて":"ご予約の変更・キャンセルは、公式LINEまたはお電話（080-4223-1203）で承ります。\n体調不良のときは遠慮なくご相談くださいね。","予約したい":{"text":"ありがとうございます。ご予約は次の方法から選べます。","reserve":true}}},"counselor":{"q1":"いちばん気になるお悩みは<br>どれですか？","q2":{"q":"いつ頃から気になっていますか？","opts":["ここ最近","半年くらい前から","ずっと前から"]},"q3":{"q":"ふだんのホームケアは？","opts":["特にしていない","化粧水・乳液くらい","美容液までしっかり"]},"concerns":{"シミ・くすみ":{"ic":"☀️","care":"美白コース（90分＋パック付き・¥11,000）","item":"ビタミンC美容液","life":"紫外線対策はくもりの日も。睡眠不足はくすみに直結するため、まずは就寝時間を30分早めるところから。"},"シワ・たるみ":{"ic":"🌙","care":"フェイシャルエステ（リンパケア重点・約90分）","item":"保湿リッチクリーム","life":"長時間の下向きスマホ姿勢はたるみのもと。目線の高さを上げ、噛みしめ癖にも気をつけてみてください。"},"ニキビ・吹き出物":{"ic":"💧","care":"フェイシャルエステ（毛穴・皮脂ケア重点・約90分）","item":"やさしい泡洗顔料","life":"脂質・糖質に偏った食事と睡眠不足は皮脂バランスを崩しがち。洗いすぎもかえって逆効果です。"},"乾燥・つっぱり":{"ic":"🍃","care":"保湿コース（90分＋パック付き・¥11,000）","item":"セラミド美容液","life":"熱いお湯での洗顔と、こすり洗いは乾燥を進めます。ぬるま湯＋やさしい泡洗顔に切り替えてみてください。"},"赤み・ゆらぎ":{"ic":"🌸","care":"フェイシャルエステ（鎮静重点・やさしい力加減で）","item":"敏感肌用ローション","life":"季節の変わり目は肌が敏感になりやすい時期。新しい化粧品を一度に増やさないのがおすすめです。"}},"disclaimer":"このご提案は美容上の一般的なアドバイスであり、医療的な診断ではありません。強い痛み・急な変化・症状が続く場合は、皮膚科など医療機関の受診をおすすめします。"},"marketing":{"media":["Instagram","Threads","LINE配信","ブログ","Googleビジネス"],"gen":{"body":{"会員制度のご案内":"【フェイシャルエステ｜会員価格のご案内】\n\n伊勢市の隠れ家サロン chainonjoli です🌿\n\nたった90分で、心がふっと軽くなる。\nフェイシャル・リンパケアの施術を\n\n・ビジター ¥8,800\n・美白コース／保湿コース（90分＋パック付き）¥11,000\n・会員 ¥3,300\n\nでご案内しています。\n\n完全予約制のプライベート空間で、日々の役割から少し離れて、自分を愛でる時間を。\n\nご予約・会員制度のご質問は、公式LINEから24時間受け付けています🌸","お客様の声":"【お客様の声】\n\n「頬のくすみが気にならなくなって、ファンデを薄くできました」\n\n4月から月1回、ホワイトニングケアに通ってくださっているお客様の言葉です☺️\n\n変化はすぐには出ません。でも、3ヶ月続けた肌は正直です。\n\n同じお悩みの方は、まずはAIカウンセラーの無料相談からどうぞ🌸","美容豆知識":"【日焼け止め、朝だけになっていませんか？】\n\n実は日焼け止めの効果は2〜3時間で落ち始めます。\n\n・お昼休みに1回だけ塗り直す\n・パウダータイプなら化粧の上からでもOK\n・くもりの日も紫外線は7割届いています\n\n夏のシミ予防は「塗り直し」がすべてです☀️\n\n詳しいケアはLINEのホームケアガイドで配布中です。","今週の空き枠案内":"【今週のご案内】\n\nこんにちは、chainonjoli です🌿\n\n今週は\n・木曜 14:00 / 16:00\n・土曜 10:00\nにお席をご用意できます。\n\n梅雨明けの集中保湿ケア、この機会にいかがですか？\n\nご予約はこのままトークにお名前とご希望時間をどうぞ。"},"tags":"#伊勢市エステ #伊勢エステ #フェイシャルエステ #リンパケア #プライベートサロン #くすみケア #乾燥肌ケア #大人肌 #ご褒美時間 #chainonjoli","reel":"【リール台本（約20秒）】\n\n0-2秒｜フック（テロップ大）\n「日焼け止め、朝だけの人〜🙋」\n\n3-8秒｜問題提起\n施術ベッドを整えながら「実は2〜3時間で効果が落ち始めます」\n\n9-15秒｜解決策（3連テロップ）\n①昼に1回塗り直す ②パウダーでもOK ③くもりの日こそ油断しない\n\n16-20秒｜締め\n「保存して、今日のお昼から試してみてね」→ プロフィールのAI相談へ誘導","img":"【画像生成プロンプト】\n\nA serene private beauty salon interior in soft morning light, beige and greige tones, a single facial treatment bed with clean white linen, small vase with dried flowers, minimal Japanese aesthetic, warm and calm atmosphere, photorealistic, 4:5 portrait"}},"quiz":[{"q":"お客様をお出迎えするとき、最初にすることは？","opts":["予約内容の確認から始める","名前でお呼びして、お荷物を預かる","施術室へ直接ご案内する"],"ans":1,"why":"chainonjoli では「お名前でのお声がけ」を最優先にしています。"},{"q":"香料アレルギーのお客様への対応は？","opts":["香りの弱い製品なら使ってよい","カルテの注意事項を確認し、指定ラインのみ使用","当日口頭で確認できればよい"],"ans":1,"why":"カルテの注意事項が最優先。佐藤様はA社ラインで統一しています。"},{"q":"当日キャンセルの連絡を受けたら？","opts":["規定どおりキャンセル料を必ず請求する","事情を伺い、体調不良なら柔軟に対応してオーナーへ報告","無料で振り替える"],"ans":1,"why":"体調不良時は柔軟対応がサロンの方針です。変更・キャンセルはLINEか電話で受け付けます。"}]}', 10, 60, '導入0号店。本番サロン')
ON CONFLICT(slug) DO UPDATE SET name=excluded.name, config=excluded.config,
